const $=id=>document.getElementById(id);const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let matches=[],revision=0;
const dictionary={tommorow:'tomorrow',tomorow:'tomorrow',recieve:'receive',recieved:'received',seperate:'separate',definately:'definitely',becuase:'because',becaus:'because',grammer:'grammar',langauge:'language',sentance:'sentence',writting:'writing',alot:'a lot',teh:'the',thier:'their',wierd:'weird',occured:'occurred',sucess:'success',succesful:'successful',enviroment:'environment',goverment:'government',accomodation:'accommodation',neccessary:'necessary',untill:'until',tommorrow:'tomorrow',studing:'studying',comming:'coming',freind:'friend',beleive:'believe',adress:'address',begining:'beginning',knowlege:'knowledge',immediatly:'immediately',responsibilty:'responsibility',acheive:'achieve'};
function basic(text){let out=[];const add=(regex,replacement,message,type='Grammar')=>{for(const m of text.matchAll(regex)){const value=typeof replacement==='function'?replacement(m):replacement;out.push({offset:m.index,length:m[0].length,replacements:[value],message,type});}};add(/\b[A-Za-z]+\b/g,m=>dictionary[m[0].toLowerCase()]||m[0],'Check this spelling.','Spelling');out=out.filter(x=>x.replacements[0]!==text.slice(x.offset,x.offset+x.length));add(/\bI am go\b/g,'I am going','Use “going” after “am”.');add(/\b(He|She|It|he|she|it) (are|were)\b/g,m=>m[1]+' '+(m[2]==='are'?'is':'was'),'Use a singular verb with this subject.');add(/\b(I|i) is\b/g,'I am','Use “am” with “I”.');add(/\b(They|We|You|they|we|you) is\b/g,m=>m[1]+' are','Use “are” with this subject.');add(/\b(He|She|he|she) don't\b/g,m=>m[1]+" doesn't",'Use “doesn’t” with he or she.');add(/\b(He|She|he|she) (go|work|want|need|like)\b/g,m=>m[1]+' '+(m[2]==='go'?'goes':m[2]+'s'),'In the simple present, add -s or -es with he or she.');add(/\b(didn't|did not) (went|saw|came|ate|wrote)\b/gi,m=>m[1]+' '+({went:'go',saw:'see',came:'come',ate:'eat',wrote:'write'}[m[2].toLowerCase()]),'Use the base verb after “did not”.');add(/\b(a) (apple|orange|umbrella|egg|hour|honest)\b/gi,m=>(m[1]==='A'?'An':'an')+' '+m[2],'Use “an” before this vowel sound.');add(/\b(an) (university|book|car|house|student)\b/gi,m=>(m[1]==='An'?'A':'a')+' '+m[2],'Use “a” before this consonant sound.');add(/\b(the|a|an|is|are|to|of|and|in)\s+\1\b/gi,m=>m[1],'This word appears twice.','Repeated word');add(/\bi\b/g,'I','Always capitalise the pronoun “I”.','Capitalisation');out.sort((a,b)=>a.offset-b.offset||b.length-a.length);let end=-1;return out.filter(x=>{if(x.offset<end)return false;end=x.offset+x.length;return true;});}
function render(){const text=$('editor').value;$('wordCount').textContent=(text.trim()?text.trim().split(/\s+/).length:0)+' words';$('count').textContent=matches.length;let html='',pos=0;matches.forEach((m,i)=>{html+=esc(text.slice(pos,m.offset))+`<button class="errorword" data-focus="${i}" title="${esc(m.message)}">${esc(text.slice(m.offset,m.offset+m.length))}</button>`;pos=m.offset+m.length;});html+=esc(text.slice(pos));$('marked').innerHTML=html;$('markedWrap').hidden=!text.trim();$('issues').innerHTML=matches.length?matches.map((m,i)=>`<div class="issue" id="issue${i}" tabindex="-1"><span class="type">${esc(m.type)}</span><p>${esc(m.message)}</p><span class="old">${esc(text.slice(m.offset,m.offset+m.length))}</span><div>${m.replacements.length?m.replacements.slice(0,3).map((r,j)=>`<button class="replacement" data-issue="${i}" data-replace="${j}">${esc(r)||'Remove'} ✓</button>`).join(''):'<p>Review this part of your sentence.</p>'}</div></div>`).join(''):`<div class="empty"><div class="check">✎</div><strong>${text.trim()?'No issues found by this check':'Your words go first.'}</strong><p class="small">${text.trim()?'You can use the online check for a broader review.':'Start writing, and common mistakes will appear here.'}</p></div>`;}
function localCheck(){revision++;matches=basic($('editor').value);render();$('status').textContent='Basic checks cover common mistakes, not every grammar or spelling error.';}
$('editor').addEventListener('input',localCheck);$('marked').onclick=e=>{const b=e.target.closest('[data-focus]');if(b){$('issue'+b.dataset.focus).focus();$('issue'+b.dataset.focus).scrollIntoView({behavior:'smooth',block:'nearest'});}};$('issues').onclick=e=>{const b=e.target.closest('[data-issue]');if(!b)return;const m=matches[+b.dataset.issue],t=$('editor').value,r=m.replacements[+b.dataset.replace];$('editor').value=t.slice(0,m.offset)+r+t.slice(m.offset+m.length);localCheck();};$('example').onclick=()=>{if($('editor').value.trim()&&!confirm('Replace your current writing with the example?'))return;$('editor').value='I am go to the office tommorow. She don\'t know the adress. We are are preparing for the exam.';localCheck();};$('clear').onclick=()=>{if($('editor').value&&!confirm('Clear your writing?'))return;$('editor').value='';localCheck();$('editor').focus();};
$('online').onclick=async()=>{const text=$('editor').value;if(!text.trim()){$('status').textContent='Write a sentence first, then check it online.';$('editor').focus();return;}if(new TextEncoder().encode(text).length>19000){$('status').textContent='Please check a shorter section of your text (under 19 KB).';return;}const version=revision;$('online').disabled=true;$('online').textContent='Checking…';$('status').textContent='Checking with LanguageTool…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('https://api.languagetool.org/v2/check',{method:'POST',body:new URLSearchParams({text,language:'en-GB'}),signal:controller.signal});if(!response.ok)throw new Error();const data=await response.json();if(revision!==version){$('status').textContent='Your text changed. Check online again for updated results.';return;}matches=data.matches.map(m=>({offset:m.offset,length:m.length,message:m.message,replacements:m.replacements.map(r=>r.value),type:m.rule?.issueType==='misspelling'?'Spelling':'Grammar & style'})).sort((a,b)=>a.offset-b.offset);let end=-1;matches=matches.filter(m=>{if(m.offset<end)return false;end=m.offset+m.length;return true;});render();$('status').textContent='Online check complete. Review suggestions before applying them.';}catch{$('status').textContent='The online service is unavailable or busy. Basic checks still work. Please try again later.';}finally{clearTimeout(timer);$('online').disabled=false;$('online').innerHTML='Check online <span>↗</span>';}};
for(const [tab,other,section,hide] of [['writeTab','readTab','writing','reading'],['readTab','writeTab','reading','writing']])$(tab).onclick=()=>{$(tab).classList.add('active');$(other).classList.remove('active');$(tab).setAttribute('aria-pressed','true');$(other).setAttribute('aria-pressed','false');$(section).hidden=false;$(hide).hidden=true;};
const passages=[{title:'Beyond the bank branch',tag:'Economy & society · Inference and argument',paragraphs:[`For many years, financial inclusion was measured chiefly by the number of bank accounts opened. This measure was convenient: accounts could be counted, targets assigned and progress displayed. Yet an account that is seldom used may change little about a household’s financial security. Access is a necessary beginning, but it does not automatically become meaningful participation.`,`Digital payments appear to bridge this gap. They reduce the distance between customers and financial services, allowing transactions without a visit to a branch. For a small trader, receiving payments electronically can create a record of earnings that may support a future loan application. However, the existence of a transaction record does not guarantee affordable credit. Lenders must still assess risk, and customers must understand the obligations they accept.`,`The barriers are not merely technological. A person may own a smartphone but share it with family members, lack confidence in resolving a failed payment, or fear losing money to fraud. When a service replaces personal assistance with a sequence of unfamiliar screens, its lower operating cost can conceal a higher burden on the customer. These difficulties are especially significant when users have limited time or literacy.`,`It would nevertheless be mistaken to conclude that digital finance has failed. The more useful question is how institutions can combine its reach with dependable human support. Local agents, clear explanations and accessible complaint mechanisms can make digital services more trustworthy. Such support should be treated as part of the service rather than a temporary concession to users who have not yet adapted.`,`A stronger measure of inclusion would therefore consider whether people can use financial services safely, regularly and for purposes they value. Counting accounts remains useful, but it should begin the evaluation, not end it. Success lies in expanding people’s practical choices, rather than merely increasing the number of products registered in their names.`],questions:[['What is the central argument of the passage?','Financial inclusion should be measured by safe, meaningful use and greater practical choice, rather than simply by the number of accounts opened.'],['Why does a digital transaction record not guarantee affordable credit?','A record may help an application, but lenders still assess risk and borrowers must understand their obligations. Having data alone does not ensure favourable loan terms.'],['What does the author mean by a “higher burden on the customer”?','Customers may have to navigate unfamiliar interfaces and resolve failures without personal assistance, requiring more time, confidence and understanding.'],['Describe the author’s attitude towards digital finance. Support your answer.','The attitude is balanced and cautiously supportive. The author recognises its reach and usefulness but argues that human support and safeguards are necessary.'],['In context, what does “concession” mean in the fourth paragraph?','An accommodation or special allowance. The author says support should be a normal part of the service, rather than a temporary accommodation for some users.']]},{title:'The price of convenience',tag:'Technology & society · Evaluating claims',paragraphs:[`Convenience is often presented as an uncomplicated benefit of technology. An application remembers an address, recommends a purchase or selects a route, removing small decisions from everyday life. Individually, each saved effort may appear trivial. Together, these services can substantially reduce the time spent on routine tasks. The question is not whether convenience has value, but whether its costs remain visible to those who enjoy it.`,`Consider a platform that ranks products according to a customer’s previous purchases. The ranking can make a large catalogue manageable, but it also shapes what the customer notices. Items outside the familiar pattern may receive little attention. A recommendation is therefore both assistance and a form of selection. It simplifies choice partly by deciding which alternatives deserve to be seen.`,`This influence does not imply that every recommendation is manipulative. People have always relied on shopkeepers, friends and critics to narrow their options. Digital systems differ in the scale and speed with which they can adapt to individual behaviour. They can also make the reasons for a recommendation difficult to understand. A user may be unable to tell whether an item appears first because it is relevant, profitable to the platform, or both.`,`Transparency is helpful, but information alone is insufficient. A lengthy explanation that few people can interpret does little to restore meaningful choice. More useful measures might allow users to change ranking preferences, view alternatives or decline personalisation without losing access to the service. Control becomes practical when exercising it requires neither specialist knowledge nor excessive effort.`,`The appropriate response is not to reject convenient technology. It is to recognise that ease and autonomy need not be opposites. Services can save time while making their influence understandable and reversible. Convenience is most valuable when it helps people pursue their own intentions rather than quietly substituting the platform’s priorities for them.`],questions:[['What concern about convenience does the passage explore?','Convenient systems can shape what people see and choose, while hiding the costs of that influence or the platform’s priorities.'],['How can a recommendation both assist and restrict a customer?','It makes a large catalogue easier to navigate, but narrows attention by selecting which products and alternatives are shown prominently.'],['Why does the author mention shopkeepers, friends and critics?','To show that relying on others to narrow choices is not new; digital systems differ in scale, speed and the opacity of their reasoning.'],['Why might transparency alone be insufficient?','Explanations may be lengthy or hard to understand. Users also need practical, simple controls to change recommendations or decline personalisation.'],['What does “autonomy” mean in the final paragraph?','The ability to make and act on one’s own choices, rather than having decisions directed by the platform’s priorities.']]},{title:'Learning that lasts',tag:'Education · Main idea and vocabulary',paragraphs:[`Students often judge a study session by how familiar the material feels at its end. Rereading a chapter can produce this familiarity quickly: the sentences become easier to recognise, and the argument seems increasingly obvious. Yet recognising an explanation while it is visible is different from reconstructing it when the book is closed. Confusing these experiences can lead students to overestimate what they have learned.`,`One alternative is to attempt an answer before consulting the material again. This exercise may feel less comfortable because it reveals gaps that smooth rereading conceals. A student who cannot explain a concept has useful information about what requires attention. The difficulty is not necessarily a sign that the session has failed; it can make the next period of study more focused.`,`However, testing oneself without checking the answer is incomplete. An incorrect explanation may persist if it is repeatedly rehearsed. Feedback should therefore follow an honest attempt, giving the learner a chance to compare the response with a sound explanation. Merely seeing the correct answer is also not enough: students must identify how their own reasoning differs and revise it.`,`Time matters as well. A student may reproduce an explanation immediately after reading it, only to struggle a few days later. Returning to a topic after an interval provides a more demanding test of understanding. The aim is not to make every session difficult, but to avoid using immediate ease as the sole measure of progress.`,`None of this makes careful reading unnecessary. Reading supplies the ideas on which later practice depends. The strongest routine connects reading, attempted recall and feedback, allowing each activity to inform the others. A productive study session may therefore end with a clearer awareness of remaining weaknesses, rather than a comforting impression that everything is already understood.`],questions:[['What distinction is central to the passage?','The distinction between recognising material when it is visible and recalling or explaining it independently. Familiarity alone is not proof of learning.'],['How can a difficult attempt at recall be useful?','It exposes gaps in understanding and shows the learner which areas need attention during further study.'],['Why should feedback follow an attempt at answering?','Without feedback, learners may repeatedly practise an incorrect explanation. Feedback lets them compare, identify errors and revise their reasoning.'],['Does the author consider rereading useless? Explain.','No. Reading supplies the ideas needed for practice. The author supports a routine that connects reading with recall and feedback rather than relying only on familiarity.'],['What does “sole” mean in the fourth paragraph?','Only or exclusive. The author argues that immediate ease should not be the only measure of progress.']]}];
let submitted=false;function loadPassage(){submitted=false;const p=passages[+$('passageSelect').value];$('passage').innerHTML=`<p class="small" style="font-family:Arial;font-size:12px;margin:0 0 16px;color:#62816e">${p.tag}</p><h2>${p.title}</h2>`+p.paragraphs.map(t=>`<p>${t}</p>`).join('');$('questionList').innerHTML=p.questions.map((q,i)=>`<div class="question"><label for="answer${i}"><strong>0${i+1}.</strong> ${esc(q[0])}</label><textarea id="answer${i}" placeholder="Write your answer in your own words…" maxlength="2500"></textarea><div class="modelanswer" id="model${i}" hidden></div></div>`).join('');$('submit').hidden=false;$('retry').hidden=true;$('quizStatus').textContent='Write your answers, then submit to compare with the model answers.';updateCount();}function updateCount(){$('answered').textContent=Array.from($('questionList').querySelectorAll('textarea')).filter(x=>x.value.trim()).length+' / 5 answered';}$('questionList').addEventListener('input',updateCount);$('passageSelect').onchange=loadPassage;$('quiz').onsubmit=e=>{e.preventDefault();const p=passages[+$('passageSelect').value];p.questions.forEach((q,i)=>{$('model'+i).hidden=false;$('model'+i).innerHTML='<strong>Model answer</strong>'+esc(q[1]);$('answer'+i).readOnly=true;});submitted=true;$('submit').hidden=true;$('retry').hidden=false;$('quizStatus').textContent='Answers revealed. Compare the meaning of your response, not the exact wording. Written answers are for self-assessment and are not automatically scored.';};$('retry').onclick=()=>{if(confirm('Clear your answers and try this passage again?'))loadPassage();};render();loadPassage();
